customCSS:
.t, .history { color: #80a0ff; }
.join { color: #60ff60; }
.part, .quit { color: #80a0ff; }
.kick, .error { color: #ff0000; }
.notice { color: #ffff00; }
.action { color: #ff00ff; }
.mode, .nick, .topic, .server { color: #40ffff; }
.highlight { color: #00ffff; background-color: #303030; border-left: 3px solid #ff00ff; padding-left: 8px; }
.reply { color: #80a0ff; border-left: 2px solid #80a0ff; padding-left: 6px; }
.oper { color: #000000; background-color: #ffff00; }
.reactions { color: #80a0ff; background-color: #303030; }
.card { background-color: #303030; border-color: #80a0ff; }
.card-title { color: #80a0ff; }
.card-desc { color: #80a0ff; }
.daychange { color: #80a0ff; border-color: #303030; }
